def solve(weights, values, capacity):
    """0/1 knapsack returning maximum total value.
    Handles weight‑zero items safely and works for any non‑negative capacity.
    """
    if capacity < 0:
        # Negative capacity cannot hold any positive‑weight item, but zero‑weight items are still allowed.
        capacity = 0
    n = min(len(weights), len(values))
    # Sum values of zero‑weight items (they can be taken without consuming capacity).
    zero_sum = 0
    pos_items = []  # (weight, value)
    for i in range(n):
        w = weights[i]
        v = values[i]
        if w == 0:
            if v > 0:
                zero_sum += v
        elif w > 0:
            pos_items.append((w, v))
        # ignore items with negative weight as undefined for 0/1 knapsack
    dp = [0] * (capacity + 1)
    for w, v in pos_items:
        for c in range(capacity, w - 1, -1):
            new_val = dp[c - w] + v
            if new_val > dp[c]:
                dp[c] = new_val
    # best value for any capacity up to given capacity
    best = max(dp)
    return best + zero_sum

