def solve(path: str) -> str:
    """Simplify an absolute Unix path.
    Handles '.', '..', multiple slashes, and ensures the result is
    an absolute path without a trailing slash (except for root)."""
    stack = []
    for part in path.split('/'):
        if not part or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
        else:
            stack.append(part)
    # Join the components with '/' and ensure a leading slash.
    return '/' + '/'.join(stack) if stack else '/'

