def solve(matrix):
    """Return the determinant of an integer matrix using Bareiss algorithm.
    Empty matrix has determinant 1.
    """
    n = len(matrix)
    if n == 0:
        return 1
    # copy matrix to avoid mutating input
    A = [row[:] for row in matrix]
    # Bareiss algorithm (fraction-free Gaussian elimination)
    det = 1
    for k in range(n-1):
        # if pivot is zero, find a non-zero row to swap
        if A[k][k] == 0:
            swap_row = None
            for i in range(k+1, n):
                if A[i][k] != 0:
                    swap_row = i
                    break
            if swap_row is None:
                return 0
            A[k], A[swap_row] = A[swap_row], A[k]
            det = -det
        pivot = A[k][k]
        for i in range(k+1, n):
            for j in range(k+1, n):
                # Perform integer update
                A[i][j] = (A[i][j]*pivot - A[i][k]*A[k][j])
                if k > 0:
                    A[i][j] //= A[k-1][k-1]
            A[i][k] = 0
        det = pivot
    return det * A[n-1][n-1]

