def solve(grid):
    """Count islands (4-directionally connected 1s) in possibly jagged grid.
    Empty grid or rows with no cells returns 0.
    """
    if not grid:
        return 0
    visited = set()
    count = 0
    rows = len(grid)
    for i, row in enumerate(grid):
        for j, val in enumerate(row):
            if val != 1 or (i,j) in visited:
                continue
            # start BFS/DFS
            count += 1
            stack = [(i,j)]
            while stack:
                x,y = stack.pop()
                if (x,y) in visited:
                    continue
                visited.add((x,y))
                # neighbours up, down, left, right
                # up
                if x-1 >= 0 and y < len(grid[x-1]) and grid[x-1][y] == 1 and (x-1,y) not in visited:
                    stack.append((x-1,y))
                # down
                if x+1 < rows and y < len(grid[x+1]) and grid[x+1][y] == 1 and (x+1,y) not in visited:
                    stack.append((x+1,y))
                # left
                if y-1 >= 0 and grid[x][y-1] == 1 and (x,y-1) not in visited:
                    stack.append((x,y-1))
                # right
                if y+1 < len(grid[x]) and grid[x][y+1] == 1 and (x,y+1) not in visited:
                    stack.append((x,y+1))
    return count

